	public static string[] FindRecipe(string givenID)
	{
		foreach (KeyValuePair<string, string[]> recipe in recipes)
		{
			for (int num = recipe.Value.Length - 1; num >= 0; num--)
			{
				if (givenID == recipe.Value[num])
				{
					return recipe.Value;
				}
			}
		}
		return null;
	}
	public static string GetMissingRecipeItem(string givenID, bool getCursed)
	{
		string[] array = FindRecipe(givenID);
		if (array != null)
		{
			string empty = string.Empty;
			for (int num = array.Length - 1; num >= 0; num--)
			{
				empty = array[num];
				if (!(empty == givenID))
				{
					if (getCursed && Item.IsCursedItem(empty))
					{
						return empty;
					}
					if (num == 0 || Random.value <= 1f / Mathf.Max((float)array.Length - 1f, 1f))
					{
						return empty;
					}
				}
			}
		}
		return string.Empty;
	}
	public static bool RecipeExists(string itemID)
	{
		return recipes.ContainsKey(itemID);
	}
	public static bool RecipeComplete(string recipeID, List<string> items)
	{
		if (!RecipeExists(recipeID))
		{
			return false;
		}
		string[] array = recipes[recipeID];
		for (int i = 0; i < array.Length; i++)
		{
			if (!items.Contains(array[i]))
			{
				return false;
			}
		}
		return true;
	}
