		if (hasFocus)
		{
			infoString = "[<color=#FFCC00>" + TextManager.GetItemName(selectedItem.ID) + "</color>]";
			if (selectedItem.isCursed)
			{
				infoString = infoString + " [<color=#FF0000>" + TextManager.GetUIText("inventory-cursedTag") + "</color>]";
			}
			if (selectedItem.isGroupItem)
			{
				infoString += (selectedItem as GroupItem).CompletionProgStr;
			}
			else if (GroupItemManager.groupsDict.ContainsKey(selectedItem.parentGroupID))
			{
				string text = infoString;
				infoString = text + "  (1/" + GroupItemManager.groupsDict[selectedItem.parentGroupID].Count + ")";
			}
			infoString = infoString + "\n" + TextManager.GetItemDescription(selectedItem.ID, player.playerID);
			infoText.text = infoString;
			SetItemFlagImages(selectedItem);
		}
	}

